import { Client, IdempotencyKey, DefaultRetryPolicy } from '@redwood/sdk'
const client = new Client({ apiKey: process.env.RW_KEY, retries: DefaultRetryPolicy })
const key = IdempotencyKey.generate('ts')
const resp = await client.createCompletion({ prompt: 'hi', idempotencyKey: key })
